import{c as t,Q as a,j as s,m as i}from"./chunks/framework.7r1mYKiJ.js";const g=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md"}'),n={name:"getting-started/installation.md"};function l(r,e,o,h,d,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Welcome to AetherUHC! This guide walks you through everything needed to get the plugin running on your Minecraft server — from downloading the JAR to launching your first match.</p><h2 id="supported-versions" tabindex="-1">Supported Versions <a class="header-anchor" href="#supported-versions" aria-label="Permalink to &quot;Supported Versions&quot;">​</a></h2><p>AetherUHC is built as a multi-module project supporting two primary Minecraft eras:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Edition</th><th style="text-align:left;">Minecraft Version</th><th style="text-align:left;">Java Version</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Legacy</strong></td><td style="text-align:left;"><code>1.8.8</code></td><td style="text-align:left;">Java 8+</td></tr><tr><td style="text-align:left;"><strong>Modern</strong></td><td style="text-align:left;"><code>1.20+</code></td><td style="text-align:left;">Java 21</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>We strongly recommend using <strong>Paper</strong> or a Paper fork (Purpur, Pufferfish) for the best performance. AetherUHC takes advantage of Paper-specific APIs for async chunk loading, world borders, and event optimizations that are unavailable on vanilla Spigot.</p></div><hr><h2 id="choosing-your-jar" tabindex="-1">Choosing Your JAR <a class="header-anchor" href="#choosing-your-jar" aria-label="Permalink to &quot;Choosing Your JAR&quot;">​</a></h2><p>There are two plugin JARs depending on your server version:</p><table tabindex="0"><thead><tr><th style="text-align:left;">JAR</th><th style="text-align:left;">Target Server</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>AetherUHC-Legacy.jar</code></td><td style="text-align:left;">1.8.8 CraftBukkit / SpigotMC</td><td style="text-align:left;">Includes NMS-based ocean removal, 1.8 crack populators</td></tr><tr><td style="text-align:left;"><code>AetherUHC.jar</code></td><td style="text-align:left;">1.20+ Paper / Purpur</td><td style="text-align:left;">Full async pregen engine, modern data pack support</td></tr></tbody></table><p>Place the appropriate JAR in your <code>plugins/</code> directory. <strong>Do not load both simultaneously.</strong></p><hr><h2 id="step-by-step-installation" tabindex="-1">Step-by-Step Installation <a class="header-anchor" href="#step-by-step-installation" aria-label="Permalink to &quot;Step-by-Step Installation&quot;">​</a></h2><h3 id="_1-download-the-plugin" tabindex="-1">1. Download the Plugin <a class="header-anchor" href="#_1-download-the-plugin" aria-label="Permalink to &quot;1. Download the Plugin&quot;">​</a></h3><p>Obtain the latest release JAR from the releases page. Confirm you have the correct edition (Legacy vs Modern).</p><h3 id="_2-place-in-plugins-folder" tabindex="-1">2. Place in Plugins Folder <a class="header-anchor" href="#_2-place-in-plugins-folder" aria-label="Permalink to &quot;2. Place in Plugins Folder&quot;">​</a></h3><p>Move the <code>.jar</code> file into your server&#39;s <code>plugins/</code> directory.</p><h3 id="_3-first-boot" tabindex="-1">3. First Boot <a class="header-anchor" href="#_3-first-boot" aria-label="Permalink to &quot;3. First Boot&quot;">​</a></h3><p>Start the server. AetherUHC will generate all default configuration files in <code>plugins/AetherUHC/</code>:</p><ul><li><code>uhcconfiguration.yml</code> — Main configuration</li><li><code>worldmanagement.yml</code> — Pre-generation and world settings</li><li><code>settings.yml</code> — Database and Redis settings</li><li><code>lang.yml</code> — All player-facing messages</li></ul><h3 id="_4-configure-database" tabindex="-1">4. Configure Database <a class="header-anchor" href="#_4-configure-database" aria-label="Permalink to &quot;4. Configure Database&quot;">​</a></h3><p>By default, AetherUHC uses SQLite and works immediately with no setup. For networked deployments requiring shared stats, see the <a href="./database.html">Database Setup</a> guide.</p><h3 id="_5-set-the-lobby-spawn" tabindex="-1">5. Set the Lobby Spawn <a class="header-anchor" href="#_5-set-the-lobby-spawn" aria-label="Permalink to &quot;5. Set the Lobby Spawn&quot;">​</a></h3><p>Join the server, navigate to where you want the lobby, and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/aetheruhc setlobby</span></span></code></pre></div><h3 id="_6-set-a-host" tabindex="-1">6. Set a Host <a class="header-anchor" href="#_6-set-a-host" aria-label="Permalink to &quot;6. Set a Host&quot;">​</a></h3><p>Grant host permissions to a player so they can use the configuration GUI:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lp user &lt;player&gt; permission set aetheruhc.host true</span></span></code></pre></div><h3 id="_7-start-your-first-match" tabindex="-1">7. Start Your First Match <a class="header-anchor" href="#_7-start-your-first-match" aria-label="Permalink to &quot;7. Start Your First Match&quot;">​</a></h3><ul><li>Type <code>/host</code> to open the Host Configuration menu.</li><li>Configure your border size, grace period, and other match settings.</li><li>Toggle scenarios with <code>/scenarios</code>.</li><li>When ready, type <code>/start</code> to begin the pre-scatter countdown.</li></ul><hr><h2 id="recommended-server-properties" tabindex="-1">Recommended Server Properties <a class="header-anchor" href="#recommended-server-properties" aria-label="Permalink to &quot;Recommended Server Properties&quot;">​</a></h2><p>Configure <code>server.properties</code> for the best UHC experience:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spawn-protection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">generate-structures</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">hardcore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=false</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">difficulty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=hard</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pvp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max-players</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=100</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">view-distance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=10</span></span></code></pre></div><hr><h2 id="recommended-paper-configuration" tabindex="-1">Recommended Paper Configuration <a class="header-anchor" href="#recommended-paper-configuration" aria-label="Permalink to &quot;Recommended Paper Configuration&quot;">​</a></h2><p>In <code>paper.yml</code> or <code>paper-global.yml</code>, consider these settings:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Allow async chunk generation (Modern only)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">async-chunks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  load-threads</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Use all available CPU cores</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Prevent automatic mob spawning during pregen</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">entity-per-chunk-save-limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  monster</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">70</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  animal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span></code></pre></div><hr><h2 id="permissions-overview" tabindex="-1">Permissions Overview <a class="header-anchor" href="#permissions-overview" aria-label="Permalink to &quot;Permissions Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Permission</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>aetheruhc.host</code></td><td style="text-align:left;">Full access to match configuration, scenarios, and start commands</td></tr><tr><td style="text-align:left;"><code>aetheruhc.admin</code></td><td style="text-align:left;">Server-level admin commands (reload, setlobby, debug)</td></tr><tr><td style="text-align:left;"><em>(none)</em></td><td style="text-align:left;">Default player commands (stats, rules, ping, helpop)</td></tr></tbody></table><hr><h2 id="troubleshooting-installation" tabindex="-1">Troubleshooting Installation <a class="header-anchor" href="#troubleshooting-installation" aria-label="Permalink to &quot;Troubleshooting Installation&quot;">​</a></h2><p><strong>The plugin doesn&#39;t load / throws errors on startup:</strong></p><ul><li>Ensure you are running the correct JAR for your server version.</li><li>Check that Java 21 is installed if using the Modern JAR (<code>java -version</code>).</li><li>Look for <code>[AetherUHC]</code> lines in <code>logs/latest.log</code> for specific error messages.</li></ul><p><strong>Commands don&#39;t appear / players can&#39;t use <code>/host</code>:</strong></p><ul><li>Make sure the player has the <code>aetheruhc.host</code> permission node.</li><li>If using LuckPerms: <code>/lp user &lt;name&gt; permission set aetheruhc.host true</code>.</li></ul><p><strong>Map generation is very slow:</strong></p><ul><li>See the <a href="./../features/world-generation.html">World Generation</a> guide for tuning options.</li><li>Consider increasing <code>PREGEN-MAX-WORKING-COUNT</code> in <code>worldmanagement.yml</code>.</li></ul><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Configure your <a href="./database.html">Database</a> for networked stat tracking.</li><li>Review all <a href="./../configuration/commands-permissions.html">Commands &amp; Permissions</a>.</li><li>Configure <a href="./../features/world-generation.html">World Generation</a> for your map.</li><li>Browse the <a href="./../features/scenarios.html">Scenario List</a> to plan your match.</li></ul>`,52)])])}const u=t(n,[["render",l]]);export{g as __pageData,u as default};
